@app.route("/backtest", methods=["GET", "POST"])
def backtest():
    default_date=(now().date()-timedelta(days=1)).strftime("%Y-%m-%d")
    race_date=request.values.get("race_date", default_date).strip()
    course=request.values.get("course", "").strip()
    race=to_int(request.values.get("race", ""), 0)
    opts=''.join(f'<option value="{html.escape(c)}" {"selected" if c==course else ""}>{html.escape(c)}</option>' for c in NAR_COURSE_CODES)
    ropts=''.join(f'<option value="{n}" {"selected" if n==race else ""}>{n}R</option>' for n in range(1,13))
    form=(
        '<div class="card"><div class="title">過去レース検証 v3.9.4</div>'
        '<div class="note">対象日のNAR公式「最終オッズ」と、そのレース時点の出馬表を使うバックテストです。結果・払戻は予想計算後に照合します。</div><div class="actions" style="margin:10px 0"><a class="btn gold" href="/backtest/bulk">過去レースを一括検証（50・100・300・500件）</a></div>'
        '<form method="post"><div class="two">'
        f'<div><label>日付</label><input type="date" name="race_date" value="{html.escape(race_date)}" max="{today()}"></div>'
        f'<div><label>競馬場</label><select name="course"><option value="">選択</option>{opts}</select></div>'
        f'<div><label>レース</label><select name="race"><option value="">選択</option>{ropts}</select></div>'
        '</div><br><button class="green">この過去レースを検証</button></form></div>'
    )
    if request.method=="GET":
        return page(form)
    try:
        dt=datetime.strptime(race_date,"%Y-%m-%d").date()
        if dt >= now().date():
            return page(form+'<div class="bad">過去に終了した日付を選んでください。</div>')
    except Exception:
        return page(form+'<div class="bad">日付を正しく選んでください。</div>')
    if course not in NAR_COURSE_CODES or not 1<=race<=12:
        return page(form+'<div class="bad">競馬場とレースを選んでください。</div>')
    try:
        horses=nar_get_horses_backtest_final(course,race,race_date)
    except Exception as e:
        return page(form+f'<div class="bad">過去オッズ取得エラー：{html.escape(type(e).__name__)} - {html.escape(str(e))}</div>')
    if not horses:
        return page(form+'<div class="note">このレースの過去単勝・複勝最終オッズを取得できませんでした。</div>')

    race_condition=nar_get_race_condition(course,race,race_date)
    distance=race_condition.get("distance")
    gate_stats={}
    if distance:
        try:
            gate_stats=gate_trend_stats_for_backtest(course,int(distance),race_date)
        except Exception:
            gate_stats={}
    try:
        form_data=nar_get_form_data(course,race,horses,race_date)
        # 重要: 現在の騎手リーディングを過去へ混ぜると未来情報になるため、
        # v3.9バックテストでは騎手名だけ表示し、騎手成績補正は中立50点にする。
    except Exception:
        form_data={}

    backtest_cal={"n":0,"hit_rate":None,"roi":None}
    result=evaluate(horses,DAILY_LIMIT,form_data,gate_stats,backtest_cal)
    if not result.get("recs"):
        return page(form+'<div class="note">候補を計算できませんでした。</div>')
    b=result["recs"][0]
    refunds=nar_get_tanfuku_refunds(course,race,race_date)
    settled=settle_tanfuku(b["horse_no"],refunds)
    fixed_return=int(settled["return_amount"]) if settled else 0
    rule_amount=recommended_amount(result["grade"],DAILY_LIMIT,b["place_low"])
    rule_return=fixed_return if rule_amount else 0
    rule_profit=rule_return-rule_amount
    fixed_profit=fixed_return-300 if settled else None
    race_text, gate_key, _, zone=gate_condition_display(course,race_condition,b,horses)
    result_lines=list(result.get("reasons") or [])
    result_lines.append(f"過去検証レース条件：{race_text}")
    result_lines.append(f"過去検証 枠比較条件：{gate_key}")
    result_lines.append("過去検証の騎手成績補正：0.0点（現在のリーディング成績を過去へ混入させないため）")
    if distance:
        try:
            result_lines.extend(gate_trend_reason_lines(course,int(distance),zone,gate_stats))
        except Exception:
            pass
    reasons=''.join(f'<li>{html.escape(x)}</li>' for x in result_lines)
    official=html.escape(settled["official_result"] if settled else "払戻取得なし")
    result_label=html.escape(settled["result"] if settled else "未取得")
    fixed_profit_text=f'{fixed_profit:+,}円' if fixed_profit is not None else '算出不可'
    body=(
        form+
        f'<div class="card"><div class="title">{html.escape(race_date)}　{html.escape(course)} {race}R 過去検証結果</div>'
        f'<div class="grade">{html.escape(result["grade"])}</div><div class="score">参考スコア {result["score"]} / 100</div>'
        '<div class="horse-card">'
        f'<div class="horse-no">{b["horse_no"]}番</div><div class="horse-name">{html.escape(b["horse_name"])}</div>'
        '<div class="pick-grid">'
        f'<div><span>単勝 最終</span><strong>{b["win_odds"]:.1f}倍</strong></div>'
        f'<div><span>複勝 最終</span><strong>{b["place_low"]:.1f}～{b["place_high"]:.1f}</strong></div>'
        f'<div><span>補正後優先度</span><strong>{b["priority_score"]:.1f}</strong></div>'
        f'<div><span>実際の結果</span><strong>{result_label}</strong></div>'
        '</div></div>'
        f'<div class="ok">NAR公式払戻：{official}</div>'
        '<div class="stats-grid">'
        f'<div><span>購入ルール</span><strong>{rule_amount:,}円</strong></div>'
        f'<div><span>ルール払戻</span><strong>{rule_return:,}円</strong></div>'
        f'<div><span>ルール収支</span><strong>{rule_profit:+,}円</strong></div>'
        f'<div><span>全ランク仮想300円収支</span><strong>{fixed_profit_text}</strong></div>'
        '</div><br>'
        f'<ul>{reasons}</ul>'
        '<div class="note">重要：過去ページから取得できるのは最終オッズなので、これは「最終オッズ基準バックテスト」です。発走5分前の実運用と完全同一ではありません。また、未来情報混入を避けるため、騎手リーディングは過去検証では中立扱いにしています。枠傾向も対象日より前のレースだけで集計します。v3.9.4でも現在の購入履歴キャリブレーションは過去検証では中立化しています。</div>'
        '</div>'
    )
    return page(body)


def run_backtest_summary(race_date, course, race):
    """1レース分のバックテスト結果をJSON化。ライブ予想や購入記録は変更しない。"""
    base={"race_date":str(race_date),"course":str(course),"race":int(race)}
    if course not in NAR_COURSE_CODES or not (1 <= int(race) <= 12):
        return {**base,"ok":False,"error":"対象外の競馬場またはレース"}
    try:
        horses=nar_get_horses_backtest_final(course,int(race),race_date)
    except Exception as e:
        return {**base,"ok":False,"error":f"最終オッズ取得エラー {type(e).__name__}"}
    if not horses:
        return {**base,"ok":False,"error":"最終オッズ取得なし"}
    try:
        rc=nar_get_race_condition(course,int(race),race_date)
    except Exception:
        rc={}
    distance=(rc or {}).get("distance")
    gate_stats={}
    if distance:
        try:
            gate_stats=gate_trend_stats_for_backtest(course,int(distance),race_date)
        except Exception:
            gate_stats={}
    try:
        form_data=nar_get_form_data(course,int(race),horses,race_date)
    except Exception:
        form_data={}
    neutral_cal={"n":0,"hit_rate":None,"roi":None}
    result=evaluate(horses,DAILY_LIMIT,form_data,gate_stats,neutral_cal)
    if not result.get("recs"):
        return {**base,"ok":False,"error":"候補計算なし"}
    b=result["recs"][0]
    refunds=nar_get_tanfuku_refunds(course,int(race),race_date)
    settled=settle_tanfuku(b["horse_no"],refunds)
    if not settled:
        return {**base,"ok":False,"error":"払戻取得なし"}
    fixed_return=int(settled["return_amount"])
    rule_amount=int(recommended_amount(result["grade"],DAILY_LIMIT,b["place_low"]))
    rule_return=fixed_return if rule_amount else 0
    official=str(settled.get("official_result") or "")
    return {
        **base,"ok":True,"grade":result["grade"],"score":int(result["score"]),
        "horse_no":int(b["horse_no"]),"horse_name":str(b["horse_name"]),
        "win_odds":float(b["win_odds"]),"place_low":float(b["place_low"]),"place_high":float(b["place_high"]),
        "priority":float(b["priority_score"]),"confidence":int(b.get("confidence") or 0),
        "market_rank":int(b.get("market_rank") or 99),"spread":float(b.get("spread") or 0.0),
        "result":str(settled["result"]),
        "win_hit":("単勝" in official),"place_hit":("複勝" in official),"official_result":official,
        "virtual_stake":300,"virtual_return":fixed_return,"virtual_profit":fixed_return-300,
        "rule_stake":rule_amount,"rule_return":rule_return,"rule_profit":rule_return-rule_amount,
    }


def _even_sample_tasks(found, limit_count):
    """期間全体から決定的に均等抽出。直近日だけに偏るのを避ける。"""
    found=list(found or [])
    n=len(found); k=max(1,int(limit_count or 1))
    if n<=k:
        return found
    if k==1:
        return [found[n//2]]
    idxs=[]; used=set()
    for i in range(k):
        idx=round(i*(n-1)/(k-1))
        if idx not in used:
            idxs.append(idx); used.add(idx)
    if len(idxs)<k:
        for idx in range(n):
            if idx not in used:
                idxs.append(idx); used.add(idx)
                if len(idxs)>=k: break
    return [found[i] for i in sorted(idxs[:k])]


def discover_backtest_tasks(start_date, end_date, course_filter, limit_count):
    start=datetime.strptime(start_date,"%Y-%m-%d").date()
    end=datetime.strptime(end_date,"%Y-%m-%d").date()
    dates=[]; d=start
    while d<=end:
        dates.append(d.strftime("%Y-%m-%d")); d+=timedelta(days=1)
    courses=[course_filter] if course_filter in NAR_COURSE_CODES else list(NAR_COURSE_CODES.keys())
    checks=[(d,c) for d in dates for c in courses]; found=[]
    if checks:
        with ThreadPoolExecutor(max_workers=min(10,len(checks))) as pool:
            fmap={pool.submit(nar_race_numbers_for_date,c,d):(d,c) for d,c in checks}
            for f in as_completed(fmap):
                d,c=fmap[f]
                try: nums=f.result()
                except Exception: nums=[]
                for r in nums: found.append({"race_date":d,"course":c,"race":int(r)})
    order={c:i for i,c in enumerate(NAR_COURSE_CODES.keys())}
    found.sort(key=lambda x:(x["race_date"],order.get(x["course"],999),x["race"]))
    return _even_sample_tasks(found,int(limit_count))


@app.route("/backtest/bulk", methods=["GET","POST"])
def backtest_bulk():
    yesterday=(now().date()-timedelta(days=1))
    default_end=yesterday.strftime("%Y-%m-%d")
    default_start=(yesterday-timedelta(days=13)).strftime("%Y-%m-%d")
    start_date=request.values.get("start_date",default_start).strip()
    end_date=request.values.get("end_date",default_end).strip()
    course=request.values.get("course","").strip()
    limit_count=to_int(request.values.get("limit","100"),100)
    if limit_count not in (50,100,300,500): limit_count=100
    opts='<option value="">全開催場</option>'+''.join(f'<option value="{html.escape(c)}" {"selected" if c==course else ""}>{html.escape(c)}</option>' for c in NAR_COURSE_CODES)
    limopts=''.join(f'<option value="{n}" {"selected" if n==limit_count else ""}>{n}レース</option>' for n in (50,100,300,500))
    form=(
        '<div class="card"><div class="title">過去レース一括バックテスト v3.9.4</div>'
        '<div class="note">NAR公式の過去最終オッズと当時の出馬表を使い、50・100・300・500レースを自動検証します。対象は期間全体から均等に抽出し、直近日だけへの偏りを抑えます。4レースずつ分割して処理するため、画面を閉じずに完了までお待ちください。</div>'
        '<form method="post"><div class="two">'
        f'<div><label>開始日</label><input type="date" name="start_date" value="{html.escape(start_date)}" max="{default_end}"></div>'
        f'<div><label>終了日</label><input type="date" name="end_date" value="{html.escape(end_date)}" max="{default_end}"></div>'
        f'<div><label>競馬場</label><select name="course">{opts}</select></div>'
        f'<div><label>最大検証数</label><select name="limit">{limopts}</select></div>'
        '</div><br><button class="green">一括検証をスタート</button></form>'
        '<div class="small" style="margin-top:8px">※過去検証では現在の騎手リーディングと現在の購入履歴キャリブレーションを中立化し、枠傾向は対象日より前だけを使用します。最終オッズ基準のため、発走5分前運用と完全同一ではありません。300・500件は処理に時間がかかります。</div></div>'
    )
    if request.method=="GET": return page(form)
    try:
        sd=datetime.strptime(start_date,"%Y-%m-%d").date(); ed=datetime.strptime(end_date,"%Y-%m-%d").date()
    except Exception:
        return page(form+'<div class="bad">日付を正しく選んでください。</div>')
    if sd>ed or ed>=now().date(): return page(form+'<div class="bad">終了済みの過去日付を、開始日≦終了日で選んでください。</div>')
    if (ed-sd).days>60: return page(form+'<div class="bad">一度に指定できる期間は61日以内です。</div>')
    try: tasks=discover_backtest_tasks(start_date,end_date,course,limit_count)
    except Exception as e: return page(form+f'<div class="bad">対象レース検索エラー：{html.escape(type(e).__name__)}</div>')
    if not tasks: return page(form+'<div class="note">指定期間に検証できるレースが見つかりませんでした。</div>')
    tasks_json=json.dumps(tasks,ensure_ascii=False).replace('</','<\\/')
    runner=r'''\n<div class="card"><div class="title">一括検証 進行状況</div><div id="progressText">準備中…</div><div style="height:14px;background:#edf1f5;border-radius:9px;overflow:hidden;margin-top:8px"><div id="progressBar" style="height:100%;width:0%;background:#2f8f5b"></div></div></div>\n<div class="card"><div class="title">集計結果</div><div id="overall" class="stats-grid"></div></div>\n<div class="card"><div class="title">ランク別 詳細</div><div id="rankTable"></div></div>\n<div class="card"><div class="title">S/Aが少ない原因分析 v3.9.4</div><div class="small">予想ロジックは変更せず、どの条件でS/Aから外れたかを集計します。複数条件を同時に満たさないレースがあるため、未達件数の合計はレース数を超えることがあります。</div><div id="causeSummary" class="stats-grid" style="margin-top:10px"></div><div id="causeTable"></div></div>\n<div class="card"><div class="title">スコア帯別 詳細</div><div class="small">スコア帯ごとに件数・的中率・単勝/複勝的中率・仮想300円回収率を比較します。ランク基準を変更する前の判断材料です。</div><div id="scoreTable"></div></div>\n<div class="card"><div class="title">期間別 詳細</div><div class="small">検証期間を最大5区間に分け、成績が一部期間だけに偏っていないか確認します。</div><div id="periodTable"></div></div>\n<div class="card"><div class="title">競馬場別 詳細</div><div class="small">件数の多い順に表示します。少数サンプルの回収率は参考値です。</div><div id="courseTable"></div></div>\n<div class="card"><div class="title">検証レース</div><div id="rows"></div></div>\n<script>\nconst tasks=__TASKS__; let done=0, results=[], failed=0;\nconst esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));\nfunction pct(a,b){return b?((a/b)*100).toFixed(1)+'%':'－'} function yen(n){return Number(n||0).toLocaleString('ja-JP')+'円'}\nfunction summary(a){const q=a.length,hh=a.filter(x=>x.result==='的中').length,wh=a.filter(x=>x.win_hit).length,ph=a.filter(x=>x.place_hit).length,vs=a.reduce((z,x)=>z+x.virtual_stake,0),vr=a.reduce((z,x)=>z+x.virtual_return,0),rs=a.reduce((z,x)=>z+x.rule_stake,0),rr=a.reduce((z,x)=>z+x.rule_return,0);return {q,hh,wh,ph,vs,vr,rs,rr}}\nfunction tableWrap(head,rows){return '<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse"><tr>'+head.map(x=>'<th>'+x+'</th>').join('')+'</tr>'+rows.join('')+'</table></div>'}\nfunction causeCount(a,fn){return a.filter(fn).length}\nfunction renderCauseAnalysis(ok){\n const sa=ok.filter(x=>x.grade==='S'||x.grade==='A'), nonSA=ok.filter(x=>x.grade!=='S'&&x.grade!=='A'), nonS=ok.filter(x=>x.grade!=='S');\n document.getElementById('causeSummary').innerHTML=`<div><span>S件数</span><strong>${ok.filter(x=>x.grade==='S').length}</strong></div><div><span>A件数</span><strong>${ok.filter(x=>x.grade==='A').length}</strong></div><div><span>S+A比率</span><strong>${pct(sa.length,ok.length)}</strong></div><div><span>B/見送り</span><strong>${nonSA.length}</strong></div>`;\n const rows=[];\n const items=[\n  ['A条件','スコア80未満',nonSA,x=>x.score<80],\n  ['A条件','候補評価76未満',nonSA,x=>x.confidence<76],\n  ['A条件','人気順位5位以下',nonSA,x=>x.market_rank>4],\n  ['A条件','複勝下限1.5倍未満',nonSA,x=>x.place_low<1.5],\n  ['S条件','スコア88未満',nonS,x=>x.score<88],\n  ['S条件','候補評価84未満',nonS,x=>x.confidence<84],\n  ['S条件','人気順位4位以下',nonS,x=>x.market_rank>3],\n  ['S条件','複勝下限1.5倍未満',nonS,x=>x.place_low<1.5],\n  ['S条件','複勝オッズ幅35%超',nonS,x=>x.spread>0.35]\n ];\n for(const [kind,label,base,fn] of items){const n=causeCount(base,fn);rows.push(`<tr><td>${kind}</td><td>${label}</td><td>${n}</td><td>${pct(n,base.length)}</td></tr>`)}\n document.getElementById('causeTable').innerHTML=tableWrap(['判定','未達条件','件数','対象内比率'],rows);\n}\nfunction renderScoreBands(ok){\n const bands=[['69以下',x=>x.score<=69],['70～74',x=>x.score>=70&&x.score<=74],['75～79',x=>x.score>=75&&x.score<=79],['80～84',x=>x.score>=80&&x.score<=84],['85～89',x=>x.score>=85&&x.score<=89],['90以上',x=>x.score>=90]],rows=[];\n for(const [label,fn] of bands){const a=ok.filter(fn),z=summary(a);rows.push(`<tr><td><b>${label}</b></td><td>${z.q}</td><td>${pct(z.hh,z.q)}</td><td>${pct(z.wh,z.q)}</td><td>${pct(z.ph,z.q)}</td><td>${pct(z.vr,z.vs)}</td><td>${z.vr-z.vs>=0?'+':''}${yen(z.vr-z.vs)}</td></tr>`)}\n document.getElementById('scoreTable').innerHTML=tableWrap(['スコア帯','件数','的中率','単勝的中','複勝的中','仮想回収率','仮想収支'],rows);\n}\nfunction update(){\n const ok=results.filter(x=>x.ok),s=summary(ok);\n document.getElementById('progressText').textContent=`${done} / ${tasks.length} レース完了　取得成功 ${s.q}　取得不可 ${failed}`;\n document.getElementById('progressBar').style.width=(tasks.length?done/tasks.length*100:0)+'%';\n document.getElementById('overall').innerHTML=`<div><span>検証成功</span><strong>${s.q}</strong></div><div><span>的中率</span><strong>${pct(s.hh,s.q)}</strong></div><div><span>全ランク仮想300円 回収率</span><strong>${pct(s.vr,s.vs)}</strong></div><div><span>仮想収支</span><strong>${s.vr-s.vs>=0?'+':''}${yen(s.vr-s.vs)}</strong></div><div><span>現行S/Aルール 購入額</span><strong>${yen(s.rs)}</strong></div><div><span>現行S/Aルール 回収率</span><strong>${pct(s.rr,s.rs)}</strong></div><div><span>現行S/Aルール 払戻</span><strong>${yen(s.rr)}</strong></div><div><span>現行S/Aルール 収支</span><strong>${s.rr-s.rs>=0?'+':''}${yen(s.rr-s.rs)}</strong></div>`;\n let rr=[]; for(const g of ['S','A','B','見送り']){const a=ok.filter(x=>x.grade===g),z=summary(a);rr.push(`<tr><td><b>${g}</b></td><td>${z.q}</td><td>${pct(z.hh,z.q)}</td><td>${pct(z.wh,z.q)}</td><td>${pct(z.ph,z.q)}</td><td>${pct(z.vr,z.vs)}</td><td>${z.vr-z.vs>=0?'+':''}${yen(z.vr-z.vs)}</td><td>${pct(z.rr,z.rs)}</td></tr>`)}\n document.getElementById('rankTable').innerHTML=tableWrap(['ランク','件数','的中率','単勝的中','複勝的中','仮想回収率','仮想収支','現行ルール回収率'],rr);\n renderCauseAnalysis(ok); renderScoreBands(ok); renderPeriods(ok); renderCourses(ok);\n}\nfunction renderPeriods(ok){\n if(!ok.length){document.getElementById('periodTable').innerHTML='－';return}\n const dates=[...new Set(ok.map(x=>x.race_date))].sort(), parts=Math.min(5,dates.length), groups=[];\n for(let i=0;i<parts;i++){const a=Math.floor(i*dates.length/parts),b=Math.floor((i+1)*dates.length/parts),ds=dates.slice(a,b); if(ds.length) groups.push(ds)}\n const rows=[]; for(const ds of groups){const set=new Set(ds),a=ok.filter(x=>set.has(x.race_date)),z=summary(a),label=ds[0]===ds[ds.length-1]?ds[0]:`${ds[0]}～${ds[ds.length-1]}`;rows.push(`<tr><td>${label}</td><td>${z.q}</td><td>${pct(z.hh,z.q)}</td><td>${pct(z.vr,z.vs)}</td><td>${z.vr-z.vs>=0?'+':''}${yen(z.vr-z.vs)}</td><td>${pct(z.rr,z.rs)}</td><td>${z.rr-z.rs>=0?'+':''}${yen(z.rr-z.rs)}</td></tr>`)}\n document.getElementById('periodTable').innerHTML=tableWrap(['期間','件数','的中率','仮想回収率','仮想収支','現行S/A回収率','現行S/A収支'],rows)\n}\nfunction renderCourses(ok){\n const names=[...new Set(ok.map(x=>x.course))].sort((a,b)=>ok.filter(x=>x.course===b).length-ok.filter(x=>x.course===a).length),rows=[];\n for(const c of names){const a=ok.filter(x=>x.course===c),z=summary(a);rows.push(`<tr><td><b>${esc(c)}</b></td><td>${z.q}</td><td>${pct(z.hh,z.q)}</td><td>${pct(z.vr,z.vs)}</td><td>${z.vr-z.vs>=0?'+':''}${yen(z.vr-z.vs)}</td><td>${pct(z.rr,z.rs)}</td><td>${z.rr-z.rs>=0?'+':''}${yen(z.rr-z.rs)}</td></tr>`)}\n document.getElementById('courseTable').innerHTML=tableWrap(['競馬場','件数','的中率','仮想回収率','仮想収支','現行S/A回収率','現行S/A収支'],rows)\n}\nfunction addRows(a){const b=document.getElementById('rows');for(const x of a){if(!x.ok){b.insertAdjacentHTML('beforeend',`<div class="note">${esc(x.race_date)} ${esc(x.course)} ${x.race}R：${esc(x.error)}</div>`);continue}b.insertAdjacentHTML('beforeend',`<div class="horse-card"><div class="horse-name">${esc(x.race_date)}　${esc(x.course)} ${x.race}R　<span class="grade">${esc(x.grade)}</span></div><div>${x.horse_no}番 ${esc(x.horse_name)}　スコア ${x.score}　候補評価 ${x.confidence}　人気 ${x.market_rank}位　結果 <b>${esc(x.result)}</b></div><div class="small">単勝 ${x.win_odds.toFixed(1)}倍 / 複勝 ${x.place_low.toFixed(1)}～${x.place_high.toFixed(1)} / オッズ幅 ${(x.spread*100).toFixed(1)}% / 仮想300円収支 ${x.virtual_profit>=0?'+':''}${yen(x.virtual_profit)} / 現行ルール ${x.rule_stake?yen(x.rule_stake):'見送り'}</div></div>`)} }\nasync function run(){for(let i=0;i<tasks.length;i+=4){const c=tasks.slice(i,i+4);try{const r=await fetch('/backtest/bulk/chunk',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tasks:c})});const d=await r.json(),a=d.results||[];results.push(...a);failed+=a.filter(x=>!x.ok).length;done+=c.length;addRows(a);update()}catch(e){failed+=c.length;done+=c.length;update()}}document.getElementById('progressText').textContent+='　✓ 完了'} update();run();\n</script>'''.replace('\\n','\n').replace('__TASKS__',tasks_json)
    return page(form+runner)


@app.post("/backtest/bulk/chunk")
def backtest_bulk_chunk():
    payload=request.get_json(silent=True) or {}; tasks=payload.get("tasks") or []
    if not isinstance(tasks,list) or len(tasks)>4: return jsonify({"results":[],"error":"invalid tasks"}),400
    clean=[]
    for t in tasks:
        try:
            d=str(t.get("race_date","")); c=str(t.get("course","")); r=int(t.get("race",0)); dt=datetime.strptime(d,"%Y-%m-%d").date()
            if dt<now().date() and c in NAR_COURSE_CODES and 1<=r<=12: clean.append((d,c,r))
        except Exception: pass
    results=[]
    if clean:
        with ThreadPoolExecutor(max_workers=min(4,len(clean))) as pool:
            fmap={pool.submit(run_backtest_summary,d,c,r):(d,c,r) for d,c,r in clean}
            for f in as_completed(fmap):
                d,c,r=fmap[f]
                try: results.append(f.result())
                except Exception as e: results.append({"race_date":d,"course":c,"race":r,"ok":False,"error":f"処理エラー {type(e).__name__}"})
    order={(d,c,r):i for i,(d,c,r) in enumerate(clean)}; results.sort(key=lambda x:order.get((x.get("race_date"),x.get("course"),int(x.get("race",0))),999))
    return jsonify({"results":results})


@app.get("/validation")
def validation():
    with db() as con:
        rows=con.execute("SELECT * FROM validation_predictions ORDER BY race_date DESC,id DESC LIMIT 300").fetchall()
    settled=[r for r in rows if r["result"] in ("的中","ハズレ")]
    n=len(settled); hits=sum(1 for r in settled if r["result"]=="的中")
    purchased=[r for r in settled if int(r["amount"] or 0)>0]
    bet=sum(int(r["amount"] or 0) for r in purchased)
    ret=sum(int(r["return_amount"] or 0) for r in purchased)
    roi=ret/bet*100 if bet else 0

    rank_cards=""
    for grade in ("S","A","B","見送り"):
        g=[r for r in settled if r["grade"]==grade]
        gn=len(g); gh=sum(1 for r in g if r["result"]=="的中")
        win_hits=sum(1 for r in g if "単勝" in str(r["official_result"] or ""))
        place_hits=sum(1 for r in g if "複勝" in str(r["official_result"] or ""))
        gp=[r for r in g if int(r["amount"] or 0)>0]
        gbet=sum(int(r["amount"] or 0) for r in gp)
        gret=sum(int(r["return_amount"] or 0) for r in gp)
        groi=(gret/gbet*100) if gbet else None
        groi_text=f"{groi:.1f}%" if groi is not None else "－"
        rank_cards+=(
            '<div class="horse-card">'
            f'<div class="horse-name">ランク {html.escape(grade)}</div>'
            '<div class="stats-grid">'
            f'<div><span>確定数</span><strong>{gn}</strong></div>'
            f'<div><span>的中率</span><strong>{(gh/gn*100 if gn else 0):.1f}%（{gh}/{gn}）</strong></div>'
            f'<div><span>単勝的中率</span><strong>{(win_hits/gn*100 if gn else 0):.1f}%（{win_hits}/{gn}）</strong></div>'
            f'<div><span>複勝的中率</span><strong>{(place_hits/gn*100 if gn else 0):.1f}%（{place_hits}/{gn}）</strong></div>'
            f'<div><span>購入額</span><strong>{gbet:,}円</strong></div>'
            f'<div><span>払戻</span><strong>{gret:,}円</strong></div>'
            f'<div><span>回収率</span><strong>{groi_text}</strong></div>'
            f'<div><span>収支</span><strong>{gret-gbet:+,}円</strong></div>'
            '</div></div>'
        )

    cards=""
    for r in rows:
        cards+=(
            '<div class="horse-card">'
            f'<div class="horse-name">{r["race_date"]}　{html.escape(r["course"])} {html.escape(r["race"])}　{r["horse_no"]}番 {html.escape(r["horse_name"])}</div>'
            '<div class="pick-grid">'
            f'<div><span>グレード</span><strong>{r["grade"]}</strong></div>'
            f'<div><span>スコア</span><strong>{r["score"]}</strong></div>'
            f'<div><span>複勝</span><strong>{r["place_low"]:.1f}～{r["place_high"]:.1f}</strong></div>'
            f'<div><span>参考EV</span><strong>{r["ev_index"]:.2f}</strong></div>'
            '</div>'
            f'<div class="small" style="margin-top:7px">結果：{r["result"]} ／ 払戻：{int(r["return_amount"] or 0):,}円 ／ 検証購入額：{int(r["amount"] or 0):,}円</div>'
            '</div>'
        )
    body=(
        '<div class="card"><div class="title">予想検証ダッシュボード v3.9</div>'
        '<form method="post" action="/validation/auto-results"><button class="green">NAR公式から未確定結果を自動取得</button></form>'
        '<div class="validation-grid" style="margin-top:10px">'
        f'<div>記録数<br><strong>{len(rows)}</strong></div><div>確定数<br><strong>{n}</strong></div>'
        f'<div>的中率<br><strong>{(hits/n*100 if n else 0):.1f}%</strong></div><div>回収率<br><strong>{roi:.1f}%</strong></div>'
        '</div>'
        f'<div class="ok">検証収支 {ret-bet:+,}円 ／ 購入額 {bet:,}円 ／ 払戻 {ret:,}円</div></div>'
        '<div class="card"><div class="title">ランク別 詳細検証</div>'
        '<div class="small">回収率・収支は実際に購入対象となる amount&gt;0 の記録だけで集計します。B・見送りの的中率は観察できます。</div>'
        f'{rank_cards}</div>'+cards
    )
    return page(body)


@app.post("/validation/auto-results")
def validation_auto_results():
    with db() as con:
        rows = con.execute(
            "SELECT * FROM validation_predictions WHERE result='未確定'"
        ).fetchall()
    updated = 0
    pending = 0
    for r in rows:
        race_no = to_int(re.sub(r"\D", "", r["race"]), 0)
        settled = settle_tanfuku(
            r["horse_no"],
            nar_get_tanfuku_refunds(r["course"], race_no, r["race_date"])
        )
        if not settled:
            pending += 1
            continue
        with db() as con:
            con.execute(
                """UPDATE validation_predictions
                SET result=?,return_amount=?,official_result=?,checked_at=?,result_source='NAR公式'
                WHERE id=?""",
                (
                    settled["result"], settled["return_amount"], settled["official_result"],
                    now().strftime("%Y-%m-%d %H:%M:%S"), r["id"]
                )
            )
        updated += 1
    return redirect(url_for("validation", updated=updated, pending=pending))



